	// Image extend mode - hold
	vec4 hold(vec2 uv, sampler2D img) {
		return texture2D(img, uv);
	}

	// Image extend mode - mirror
	vec4 mirror(vec2 uv, sampler2D img) {
		vec2 iuv = floor(uv);
		uv *= 1.-2.*mod(iuv, 2.);
		return texture2D(img, fract(uv));
	}

	// Image extend mode - one
	vec4 one(vec2 uv, sampler2D img) {
		if (0. <= uv.x && uv.x <= 1. && 0. <= uv.y && uv.y <= 1.) {
			return texture2D(img, uv);
		}
		else { return vec4(1.); }
	}

	// Image extend mode - repeat
	vec4 repeat(vec2 uv, sampler2D img) {
		return texture2D(img, fract(uv));
	}

	// Image extend mode - zero
	vec4 zero(vec2 uv, sampler2D img) {
		if (0. <= uv.x && uv.x <= 1. && 0. <= uv.y && uv.y <= 1.) {
			return texture2D(img, uv);
		}
		else { return vec4(0.); }
	}

	// Coordinate extend mode - mirror
	vec2 mirror(vec2 uv, float num) {
		uv *= num;
		vec2 iuv = floor(uv);
		uv *= 1.-2.*mod(iuv, 2.);
		return fract(uv);
	}

	// Coordinate extend mode - mirror
	vec2 mirror(vec2 uv, vec2 grid) {
		uv *= grid;
		vec2 iuv = floor(uv);
		uv *= 1.-2.*mod(iuv, 2.);
		return fract(uv);
	}

	// Coordinate extend mode - repeat
	vec2 repeat(vec2 uv, float num) {
		return fract(uv*num);
	}

	// Coordinate extend mode - repeat
	vec2 repeat(vec2 uv, vec2 grid) {
		return fract(uv*grid);
	}
`

// === Tab: frag ===
// noprotect

const frag = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	uniform vec2 iResolution;
	uniform float iPixelDensity;
	uniform sampler2D iCanvas;
	uniform vec2 iMouse;
	uniform float iTime;

	${ displace }
	${ snoise3D }
	${ snoise3DImage }
	${ gradient }
	${ Palette }
	${ extendMode }

	float smoo3(float x) { return x*x*(3.-2.*x); }
	vec2 smoo3(vec2 x) { return x*x*(3.-2.*x); }
	vec3 smoo3(vec3 x) { return x*x*(3.-2.*x); }
	vec4 smoo3(vec4 x) { return x*x*(3.-2.*x); }

	varying vec2 vTexCoord;
	void main() {
		vec2 uv = vTexCoord;
		vec2 mouse = iMouse.xy/iResolution.xy;
		mouse = min(max(vec2(0.), mouse), vec2(1.));

		uv-=0.5;
		uv.x *= iResolution.x/iResolution.y;

		vec2 muv = smoo3(mirror(uv, 1.));

		float scal = 2.;
		float gain = mouse.y*100.;
		float ofst = .5;
		float expo = mouse.x*2.5;
		vec3  move = vec3(0., 0., iTime*0.0025);
		vec4 dimg = snoise3DImage(1.*uv, scal, gain, ofst, expo, move);

		float wei = 0.1;
		vec2 duv = smoo3(displace(muv, dimg.rg, ofst, wei));

		vec2 puv = smoo3(conical(duv, vec2(.5), 5., iTime*0.001));

		vec4 color = smoo3(Palette(puv));

		gl_FragColor = smoo3(color);
	}
`

// === Tab: vert ===
// Basic structure ref: https://itp-xstory.github.io/p5js-shaders/#/./docs/how-to-write-a-shader

const vert = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	varying vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
		gl_Position = positionVec4;
	}
`

